if (IsPolymorphed())
	return false;

// MT2009_PLUS_SMH_TOWER_V1 (skills): Wieza Sung Mahi's curse "Umiejetnosci sa zablokowane" (pl-wiki) - the
// affect 1849 the quest wieza_sung_mahi lays on a room (d.affect_all) blocks every skill until the room ends.
if (FindAffect(1849))
{
	ChatPacket(CHAT_TYPE_INFO, "Klatwa Sunga Mahi blokuje twoje umiejetnosci.");
	return false;
}

// MT2009_PLUS_DRAGON_ROAR_TARGET_V1

sys_log(0, "%s: USE_ITEM %s (inven %d, cell: %d)", GetName(), item->GetName(), window_type, wCell);

// MT2009_PLUS_SMH_TOWER_V1 (potions): Handlarka's (9014) tower potions 70390-70395 - Czerwona/Niebieska Mikstura (W),
// Wino Brzoskwini (W), Blogoslawienstwa Zycia/Magii/Smoka (W) - work only inside Wieza Sung Mahi (map 387 and its
// instances 387xxxx), as officially ("Mozna uzyc tylko w Piekielnej Wiezy Sunga Mahi").
if (item->GetVnum() >= 70390 && item->GetVnum() <= 70395)
{
	const long lSmhMap = GetMapIndex() >= 10000 ? GetMapIndex() / 10000 : GetMapIndex();
	if (lSmhMap != 387)
	{
		ChatPacket(CHAT_TYPE_INFO, "Tego przedmiotu mozna uzyc tylko w Piekielnej Wiezy Sunga Mahi.");
		return false;
	}
}
